type EmitCb = extern "C" fn(*const c_char, *const c_char, *mut c_void);
struct EmitState {
    cb: Option<(EmitCb, usize)>,
}
unsafe impl Send for EmitState {}
static EMIT: Mutex<EmitState> = Mutex::new(EmitState { cb: None });

fn emit_event(name: &str, payload: &serde_json::Value) {
    let state = EMIT.lock().unwrap();
    if let Some((cb, ud)) = state.cb {
        let name_c = CString::new(name).unwrap_or_default();
        let json_c = CString::new(payload.to_string()).unwrap_or_default();
        cb(name_c.as_ptr(), json_c.as_ptr(), ud as *mut c_void);
    }
}

