pub trait WidespreadWalletModule: 'static {
    /// One-time setup hook: fires after the host has stamped the module
    /// context (path / instance id / persistence path) and before the
    /// first method dispatch — the Rust analog of C++'s
    /// LogosModuleContext::onContextReady().
    fn on_context_ready(&mut self, _ctx: &RustModuleContext) {}

    /// Called when the host is about to unload this module, before the
    /// implementation is dropped. Return `Synchronous` (the default)
    /// when teardown finished inline, or `Asynchronous` to keep the
    /// host waiting until `logos_rust_sdk::unload_finished()` is
    /// called. The host enforces a grace period either way.
    fn about_to_unload(&mut self) -> logos_rust_sdk::Shutdown {
        logos_rust_sdk::Shutdown::Synchronous
    }

    fn execute(&mut self, op: Vec<u8>) -> Vec<u8>;
    fn connect(&mut self, dapp_info: Vec<u8>) -> Vec<u8>;
    fn get_accounts(&mut self) -> Vec<u8>;
    fn get_balance(&mut self, account: String) -> Vec<u8>;
    fn propose_transaction(&mut self, request: Vec<u8>) -> Vec<u8>;
    fn get_status(&mut self) -> Vec<u8>;
}

type DispatchFn = fn(&str, &[serde_json::Value]) -> Option<serde_json::Value>;
type EnsureFn = fn(bool);
// Reaches the author's impl from the teardown C export, which is a
// free function with no `T` -- exactly why `dispatch` is reached
// this way too.
type AboutToUnloadFn = fn() -> i32;
struct Registered {
    dispatch: DispatchFn,
    ensure: EnsureFn,
    // Read only by the teardown export, which is emitted for
    // protocol >= 0.5; an older module registers the hook and
    // never calls it.
    #[allow(dead_code)]
    about_to_unload: AboutToUnloadFn,
}
static REGISTERED: Mutex<Option<Registered>> = Mutex::new(None);
// A concurrency:"single" module runs entirely on one thread (its
// subprocess event loop): install / on_context_ready / dispatch all touch
// INSTANCE from that thread, so the impl never crosses threads and need
// not be Send. This single-threaded Sync wrapper lets a non-Send impl
// live in a static (cf. the EmitState unsafe impl above).
struct SingleInstance(Mutex<Option<Box<dyn std::any::Any>>>);
unsafe impl Sync for SingleInstance {}
static INSTANCE: SingleInstance = SingleInstance(Mutex::new(None));
static HOOK_FIRED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

